  return {
    page,
    values,
    messages,
    invalid,
    navigate(pageId) {
      setPage(pageId);
      setMessages({});
      setInvalid({});
    },
    setValue(id, value) {
      setValues((current) => ({ ...current, [id]: value }));
      setInvalid((current) => ({ ...current, [id]: false }));
    },
    showMessage(owner, text, tone) {
      setMessages((current) => ({ ...current, [owner]: { text, tone } }));
    },
    clearMessage(owner) {
      setMessages((current) => ({ ...current, [owner]: null }));
    },
    markInvalid(ids) {
      setInvalid((current) => ({ ...current, ...Object.fromEntries(ids.map((id) => [id, true])) }));
    },
    toggle(id) {
      setHidden((current) => ({ ...current, [id]: !current[id] }));
    },
    setText(id, text) {
      setTexts((current) => ({ ...current, [id]: text }));
    },
    isHidden: (id) => Boolean(hidden[id]),
    textOf: (id, fallback) => texts[id] ?? fallback,
  };
}

/** Attributes every generated element carries, plus the shared UI store. */
function useNode(id, type) {
  const ui = useUI();
  const attrs = { "data-ngid": id, "data-ngtype": type, hidden: ui.isHidden(id) || undefined };
  return { ui, attrs };
}

const FORMATS = {
  email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
  phone: /^\+?[\d\s()-]{7,}$/,
  number: /^-?\d+(\.\d+)?$/,
};

function isEmpty(value) {
  return value === undefined || value === null || value === false || String(value).trim() === "";
}

/**
 * Run an event's actions in order. A failing validation shows its message
 * (role="alert", data-ngmsg=owner) and stops the chain.
 */
function runActions(owner, actions, ui) {
  ui.clearMessage(owner);
  for (const action of actions) {
    switch (action.type) {
      case "validate_required": {
        const missing = action.targets.filter((id) => isEmpty(ui.values[id]));
        if (missing.length > 0) {
          ui.markInvalid(missing);
          ui.showMessage(owner, action.message, "error");
          return false;
        }
        break;
      }
      case "validate_format": {
        const value = String(ui.values[action.target] ?? "").trim();
        if (!FORMATS[action.format].test(value)) {
          ui.markInvalid([action.target]);
          ui.showMessage(owner, action.message, "error");
          return false;
        }
        break;
      }
      case "show_message":
        ui.showMessage(owner, action.text, action.tone || "info");
        break;
      case "navigate":
        ui.navigate(action.page);
        break;
      case "toggle_visibility":
        ui.toggle(action.target);
        break;
      case "set_text":
        ui.setText(action.target, action.text);
        break;
      default:
        console.warn(`Unknown action: ${action.type}`);
    }
  }
  return true;
}

/** Flex container shared by pages, cards, forms, headers, navbars and plain containers. */
function Stack({ id, type, as: Tag = "div", layout = {}, style, children, onSubmit }) {
  const { attrs } = useNode(id, type);
  const { direction = "column", gap = 12, align = "stretch", justify = "start" } = layout;
  const className = `ng-${type} ng-stack ng-stack--${direction} ng-align-${align} ng-justify-${justify}`;
  const handleSubmit = onSubmit
    ? (event) => {
        event.preventDefault();
        onSubmit(event);
      }
    : (event) => event.preventDefault();

  return (
    <Tag {...attrs} className={className} style={{ gap, ...style }} onSubmit={Tag === "form" ? handleSubmit : undefined}>
      {children}
    </Tag>
  );
}

function Page(props) {
  return <Stack {...props} type="page" as="main" />;
}

function LoginPage() {
  const { ui } = useNode("page_login", "page");

  function onSubmit() {
    // Validate required fields
    const valid = runActions("login_form", [
      { type: "validate_required", targets: ["email", "password"], message: "Please fill in all required fields." },
      { type: "validate_format", target: "email", format: "email", message: "Please enter a valid email address." },
      { type: "show_message", text: "Login successful!", tone: "success" },
    ], ui);
    if (valid) {
      // For demo, just show success message
      // In real app, would handle login logic here
    }
  }

  return (
    <Page id="page_login" layout={{ gap: 16 }}>
      <h1 className="ng-heading ng-heading--1">Login</h1>
      <form className="ng-form" onSubmit={(e) => { e.preventDefault(); onSubmit(); }} noValidate>
        <Stack id="login_form" type="form" layout={{ gap: 16 }}>
          <div className="ng-field">
            <label htmlFor="email" className="ng-field__label">
              Email<span className="ng-field__required" aria-hidden="true">*</span>
            </label>
            <input
              id="email"
              name="email"
              type="email"
              className="ng-input"
              aria-invalid={ui.invalid.email ? "true" : undefined}
              aria-describedby={ui.invalid.email ? "email-error" : undefined}
              value={ui.values.email || ""}
              onChange={(e) => ui.setValue("email", e.target.value)}
              required
              autoComplete="email"
            />
            {ui.invalid.email && ui.messages.login_form && (
              <p id="email-error" role="alert" className="ng-msg ng-msg--error">
                {ui.messages.login_form.text}
              </p>
            )}
          </div>
          <div className="ng-field">
            <label htmlFor="password" className="ng-field__label">
              Password<span className="ng-field__required" aria-hidden="true">*</span>
            </label>
            <input
              id="password"
              name="password"
              type="password"
              className="ng-input"
              aria-invalid={ui.invalid.password ? "true" : undefined}
              aria-describedby={ui.invalid.password ? "password-error" : undefined}
              value={ui.values.password || ""}
              onChange={(e) => ui.setValue("password", e.target.value)}
              required
              autoComplete="current-password"
            />
            {ui.invalid.password && ui.messages.login_form && (
              <p id="password-error" role="alert" className="ng-msg ng-msg--error">
                {ui.messages.login_form.text}
              </p>
            )}
          </div>
          {ui.messages.login_form && ui.messages.login_form.tone === "success" && (
            <p role="alert" className="ng-msg ng-msg--success">
              {ui.messages.login_form.text}
            </p>
          )}
          <button type="submit" className="ng-btn ng-btn--primary ng-btn--md">
            Login
          </button>
        </Stack>
      </form>
    </Page>
  );
}

function MainPage() {
  return (
    <Page id="page_main" layout={{ gap: 16 }}>
    </Page>
  );
}

const PAGES = {
  page_main: MainPage,
  page_login: LoginPage,
};

const INITIALLY_HIDDEN = {};

function App() {
  const ui = useUIStore("page_login", INITIALLY_HIDDEN);
  const CurrentPage = PAGES[ui.page] ?? MainPage;

  return (
    <UIContext.Provider value={ui}>
      <div className="ng-app">
        <CurrentPage />
      </div>
    </UIContext.Provider>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
